CREATE TABLE `ydy_table_tech_skillrow` (
          `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
          `cid` varchar(64) DEFAULT NULL,
          `time` datetime DEFAULT NULL,
          `customer` varchar(128) DEFAULT NULL,
          `staff_uuid` varchar(64) DEFAULT NULL,
          `terminalMac` varchar(128) DEFAULT NULL,
          `deviceName` varchar(256) DEFAULT NULL,
          `device_id` varchar(64) DEFAULT NULL,
          `productKey` varchar(64) DEFAULT NULL,
          `elapsedTime` varchar(64) DEFAULT NULL,
          `energyPerHour` varchar(64) DEFAULT NULL,
          `energyPerMinute` varchar(64) DEFAULT NULL,
          `energyTotal` varchar(64) DEFAULT NULL,
          `met` varchar(64) DEFAULT NULL,
          `paceAverage` varchar(64) DEFAULT NULL,
          `paceInstantaneous` varchar(64) DEFAULT NULL,
          `powerAverage` varchar(64) DEFAULT NULL,
          `powerInstantaneous` varchar(64) DEFAULT NULL,
          `resistanceLevel` varchar(64) DEFAULT NULL,
          `strokeAverageRate` varchar(64) DEFAULT NULL,
          `strokeCount` varchar(64) DEFAULT NULL,
          `strokeRate` varchar(64) DEFAULT NULL,
          `totalDistance` varchar(64) DEFAULT NULL,
          `date` datetime DEFAULT NULL,
          PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8 ROW_FORMAT=COMPACT COMMENT='泰诺健划船机阿里云tableStore格式化数据表'